#!/usr/bin/env bash
# Commit the removal of every upstream workflow, keeping only this fork's own.
#
#   prune_upstream_workflows.sh [--keep linux-sbx-weekly.yml] [--output FILE]
#
# Runs on the checked-out branch right after rebase_onto_tag.sh. The fork only
# needs .github/workflows/linux-sbx-weekly.yml; every other file under
# .github/workflows/ came from upstream. Deleting them in one generated commit
# keeps upstream's release, nightly and CI workflows from registering (or
# running) in the fork once the branch is pushed.
#
# The commit is reproducible: fixed bot identity, author and committer dates
# taken from its parent, so the same rebased tree always yields the same sha
# (publish_local.sh then has nothing to push, and no new prerelease is made
# for a commit that already has one). It carries the trailer
#
#   Linux-Sbx-Generated: prune-upstream-workflows
#
# which rebase_onto_tag.sh uses to drop it before the next replay; it is then
# generated again on top of the new tag.
#
# Outputs (--output, default $GITHUB_OUTPUT): sha=<HEAD> pruned=<count>.
# Exit 1 if the kept workflow is missing: the rebased tree would have no
# workflow left to run next week.
set -euo pipefail

KEEP="linux-sbx-weekly.yml"
OUTPUT="${GITHUB_OUTPUT:-}"
DIR=".github/workflows"
TRAILER="Linux-Sbx-Generated: prune-upstream-workflows"

while [[ $# -gt 0 ]]; do
    case "$1" in
        --keep) KEEP="$2"; shift 2 ;;
        --output) OUTPUT="$2"; shift 2 ;;
        -h|--help) sed -n '2,23p' "$0"; exit 0 ;;
        *) echo "unknown argument: $1" >&2; exit 2 ;;
    esac
done

git rev-parse --git-dir >/dev/null 2>&1 || { echo "error: not inside a git checkout" >&2; exit 1; }
if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
    echo "error: the checkout has uncommitted changes; refusing to commit on top of them" >&2
    exit 1
fi
if ! git cat-file -e "HEAD:$DIR/$KEEP" 2>/dev/null; then
    echo "error: $DIR/$KEEP is not in HEAD; the pruned tree would have no workflow left" >&2
    exit 1
fi

DOOMED=()
while IFS= read -r -d '' path; do
    [[ $path == "$DIR/$KEEP" ]] || DOOMED+=("$path")
done < <(git ls-files -z -- "$DIR")

if [[ ${#DOOMED[@]} -gt 0 ]]; then
    git rm --quiet -- "${DOOMED[@]}"
    DATE="$(git log -1 --format=%cI HEAD)"
    GIT_AUTHOR_NAME="github-actions[bot]" \
    GIT_AUTHOR_EMAIL="41898282+github-actions[bot]@users.noreply.github.com" \
    GIT_COMMITTER_NAME="github-actions[bot]" \
    GIT_COMMITTER_EMAIL="41898282+github-actions[bot]@users.noreply.github.com" \
    GIT_AUTHOR_DATE="$DATE" GIT_COMMITTER_DATE="$DATE" \
        git -c commit.gpgsign=false commit --quiet --no-verify \
            -m "ci(linux-sbx): keep only ${KEEP} in this fork" \
            -m "Removes ${#DOOMED[@]} upstream workflow file(s). Generated by prune_upstream_workflows.sh after each weekly rebase; dropped and regenerated on the next one." \
            -m "$TRAILER"
    echo "pruned ${#DOOMED[@]} upstream workflow file(s); kept $DIR/$KEEP" >&2
else
    echo "nothing to prune: $DIR/$KEEP is the only workflow" >&2
fi

SHA="$(git rev-parse HEAD)"
if [[ -n $OUTPUT ]]; then
    printf 'sha=%s\npruned=%s\n' "$SHA" "${#DOOMED[@]}" >>"$OUTPUT"
fi
echo "$SHA"
